/** Backwards-compatible alias */
export const TABLER_PATHS = SOLAR_PATHS;

export type IconName = keyof typeof SOLAR_PATHS | string;

export function getIconSvg(name: string, options: IconOptions = {}): string {
  const size = options.size ?? 24;
  const className = options.className ? `class="${options.className}"` : '';
  const style = options.style ? `style="${options.style}"` : '';
  
  const targetName = name;
  const body = SOLAR_PATHS[targetName] || SOLAR_PATHS[name] || '';
  
  // Third-party brand logos (e.g. GitHub, X, Facebook, Instagram)
  const isBrand = targetName.startsWith('brand-') || targetName.startsWith('github') || targetName.startsWith('facebook') || targetName.startsWith('instagram') || targetName.startsWith('twitter');
  
  // Bold / Filled icons (Solar Bold collection, or any explicit -bold / -fill icon)
  const isExplicitBold = targetName.endsWith('-bold') || targetName.endsWith('-fill') || targetName.endsWith('-filled');
  const isBold = isExplicitBold || (!body.includes('stroke=') && (body.includes('fill="currentColor"') || body.includes('fill-rule=')));
  
  if (isBrand || isBold) {
    const fillColor = options.fill || options.color || 'currentColor';
    return `<svg ${className} ${style} width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fillColor}">${body}</svg>`;
  }
  
  // Solar Linear stroke icon (1.5px outline)
  const strokeColor = options.color || 'currentColor';
  const strokeWidth = options.strokeWidth ?? 1.5;
  const fillColor = options.fill || 'none';
  return `<svg ${className} ${style} width="${size}" height="${size}" viewBox="0 0 24 24" fill="${fillColor}" stroke="${strokeColor}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
}

